    if (v >= 75) return {label:'Strong',  ic:'r-interp-green', fc:'r-score-fill-green'};
    if (v >= 55) return {label:'Growing', ic:'r-interp-amber', fc:'r-score-fill-amber'};
    if (v >= 35) return {label:'Quiet',   ic:'r-interp-gray',  fc:'r-score-fill-gray'};
